# OpenAI 风格 structured outputs（strict JSON Schema）
schema = {
    "type": "object",
    "properties": {
        "name": {"type": "string"},
        "age": {"type": "integer"},
        "tags": {"type": "array", "items": {"type": "string"}}
    },
    "required": ["name", "age"],
    "additionalProperties": False
}
# response_format={"type": "json_schema",
#                  "json_schema": {"name": "person", "schema": schema, "strict": True}}
# strict=True 时底层用约束解码，保证输出严格匹配 schema

# 工程兜底：即便如此也要校验 + 重试语义错误
import json, jsonschema
def parse_safe(text):
    obj = json.loads(text)            # 约束解码保证可解析
    jsonschema.validate(obj, schema)  # 再校验业务约束
    return obj
